app.Use(async (context,next)=>{context.Response.Headers["X-Content-Type-Options"]="nosniff";context.Response.Headers["X-Frame-Options"]="DENY";context.Response.Headers["Referrer-Policy"]="no-referrer";context.Response.Headers["Permissions-Policy"]="camera=(self), microphone=(self), geolocation=(self), payment=(), usb=(), serial=()";context.Response.Headers["Content-Security-Policy"]="default-src 'self'; base-uri 'self'; object-src 'none'; frame-ancestors 'none'; frame-src 'self' https://www.openstreetmap.org; form-action 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; media-src 'self' blob:; connect-src 'self' https://nominatim.openstreetmap.org; worker-src 'self' blob:";context.Response.Headers["Cross-Origin-Opener-Policy"]="same-origin";context.Response.Headers["X-Permitted-Cross-Domain-Policies"]="none";context.Response.Headers["X-Application-Release"]="V327";if(context.Request.IsHttps)context.Response.Headers["Strict-Transport-Security"]="max-age=31536000; includeSubDomains";context.Response.OnStarting(()=>{var path=context.Request.Path.Value??"";if(context.Response.ContentType?.Contains("text/html",StringComparison.OrdinalIgnoreCase)==true||path.Equals("/release-guard.js",StringComparison.OrdinalIgnoreCase)||path.Equals("/version-web.json",StringComparison.OrdinalIgnoreCase)){context.Response.Headers.CacheControl="no-store, no-cache, must-revalidate";context.Response.Headers.Pragma="no-cache";context.Response.Headers.Expires="0";}return Task.CompletedTask;});await next();});
